args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  <http://dbpedia.org/resource/Elizabeth_Howard,_Countess_of_Effingham> ?spP ?spouse .
  FILTER(regex(str(?spP), "spouse", "i"))
  {
    ?spouse <http://dbpedia.org/property/father> ?father .
  } UNION {
    ?spouse <http://dbpedia.org/ontology/parent> ?father .
  } UNION {
    ?spouse <http://dbpedia.org/property/parent> ?father .
  } UNION {
    ?father <http://dbpedia.org/property/children> ?spouse .
  } UNION {
    ?father <http://dbpedia.org/ontology/child> ?spouse .
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
} LIMIT 50

